/**
 * @fileoverview Test the usage of a deprecated Class
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-deprecated-class-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-deprecated-class-usage', rule, {

    valid: [

    ],

    invalid: [
        {
            settings: {
                extjs: {
                    fromVersion: '4.0',
                    toVersion: '7.9.0'
                }
            },
            code: `
                var type = 'trigger';
                Ext.create({
                    xtype: type,
                    itemId: testartName,
                    title: testart.data.value,
                    features: gridFeatures
                });

                Ext.define('MyCustomComponent', {
                    extend: 'Ext.panel.Panel',
                    initComponent: function () {
                        var type = 'trigger';
                        var trigger = Ext.create({
                            xtype: type,
                            itemId: testartName,
                            title: testart.data.value,
                            features: gridFeatures
                        });
                        this.callParent();
                        this.add(trigger);
                    }
                });
                // TODO - add support for this type of code
                // this example was found in the framework code at /packages/core/src/class/Base.js
                Ext.create.apply(Ext, [this].concat(Array.prototype.slice.call(arguments, 0)));
            `,
            errors: [
                { message: /Usage of deprecated Class 'Ext.form.field.Trigger' found.*/ },
                { message: /Usage of deprecated Class 'Ext.form.field.Trigger' found.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                var MyCustomClass = Ext.extend(Ext.AbstractManager, {
                    customProp: true
                });
                var MyCustomManagerClass = Ext.extend(true ? Ext.AbstractManager : Ext.EventManager, {
                    customProp: true
                });
                Ext.define('MyCustomClass', {
                    extend: 'Ext.data.Error'
                });
            `,
            errors: [
                { message: /Usage of deprecated Class 'Ext.AbstractManager' found.*/ },
                { message: /Usage of deprecated Class 'Ext.AbstractManager' found.*/ },
                { message: /Usage of deprecated Class 'Ext.EventManager' found.*/ },
                { message: /Usage of deprecated Class 'Ext.data.Error' found.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('Ext4App.view.Container', {
                    extend: 'Ext.Container',
                    xtype: 'app-container',
                    items: [{
                        xtype: 'triggerfield', // should warn
                        fieldLabel: 'My TriggerField',
                        onTriggerClick: function () {
                            Ext.Msg.alert('Status', 'You clicked my trigger!');
                        }
                    }],
                    someMethod: function () {
                        this.add({xtype: 'triggerfield'});
                        this.add({xtype: 'trigger'});

                        Ext.create('widget.triggerfield', {});
                        Ext.create('widget.trigger', {});

                        Ext.widget('triggerfield', {});
                        Ext.widget('trigger', {});

                        Ext.create({xtype: 'triggerfield'});
                        Ext.create({xtype: 'trigger'});

                        Ext.create({xclass: 'Ext.form.field.Trigger'});
                        Ext.create({xclass: 'Ext.form.Trigger'});
                        Ext.create({xclass: 'Ext.form.TriggerField'});
                        Ext.create({xclass: 'Ext.form.TwinTriggerField'});

                        Ext.create('Ext.form.field.Trigger', {});
                        Ext.create('Ext.form.Trigger', {});
                        Ext.create('Ext.form.TriggerField', {});
                        Ext.create('Ext.form.TwinTriggerField', {});

                        new Ext.form.field.Trigger({});
                        new Ext.form.Trigger({});
                        new Ext.form.TriggerField({});
                        new Ext.form.TwinTriggerField({});
                    }
                });
                Ext.define('MyCustomTrigger', {
                    extend: 'Ext.form.field.Trigger'
                });
                Ext.define('overrides.TriggerField', {
                    override: 'Ext.form.field.Trigger'
                });
                var MyCustomTrigger = Ext.extend(Ext.form.field.Trigger, {});
                Ext.form.field.Trigger.prototype.customMethod = function () {};
            `,
            errors: 25
        }
    ]
});
